    const missingPfx = !pfxConfig.pfx;
    debug('missingPfx', missingPfx);

    if (missingKeyCert && missingPfx) {
      debug('No HTTPS configuration found');
      logHTTPSWarning(configPath);
      throw new Error('No HTTPS configuration found');
